+      const ctx = c.getContext('2d');
+      ctx.fillStyle = '#6f4e37';
+      ctx.fillRect(0, 0, 512, 512);
+
+      const plankH = 64;
+      for (let y = 0; y < 512; y += plankH) {
+        const row = y / plankH;
+        const offset = (row % 2) * 128;
+        for (let x = -128; x < 512; x += 256) {
