+          ctx.lineWidth = 1;
+          for (let g = 0; g < 8; g++) {
+            ctx.beginPath();
+            const gy = y + 6 + g * 7;
+            ctx.moveTo(x + offset, gy);
+            ctx.bezierCurveTo(
+              x + offset + 80, gy + ((g % 2) ? 2 : -2),
+              x + offset + 170, gy + ((g % 2) ? -2 : 2),
