+      const cols = 8;
+      const bh = 512 / rows;
+      const bw = 512 / cols;
+      for (let r = 0; r < rows; r++) {
+        const shift = (r % 2) * (bw * 0.5);
+        for (let col = -1; col <= cols; col++) {
