+    // Helper: Build Finned-Tube Heat Exchanger Coil Geometry
+    // -------------------------------------------------------------------------
+    function createHeatExchangerMesh(widthZ, heightY, depthX, finCount, coilMaterial) {
+      const group = new THREE.Group();
+
+      // Aluminum fin pack
+      const finGeo = new THREE.BoxGeometry(depthX, heightY, 0.008);
+      for (let i = 0; i < finCount; i++) {
+        const fz = -widthZ * 0.5 + (i / (finCount - 1)) * widthZ;
+        const fin = new THREE.Mesh(finGeo, coilMaterial);
+        fin.position.z = fz;
+        group.add(fin);
+      }
+
+      // Serpentine copper refrigerant passes running horizontally across the coil
+      const rows = 5;
+      const tubeGeo = new THREE.CylinderGeometry(0.022, 0.022, widthZ + 0.08, 12);
+      tubeGeo.rotateX(Math.PI * 0.5);
+      for (let r = 0; r < rows; r++) {
+        const ry = -heightY * 0.4 + (r / (rows - 1)) * (heightY * 0.8);
+        const pass1 = new THREE.Mesh(tubeGeo, coilMaterial);
+        pass1.position.set(-depthX * 0.22, ry, 0);
+        const pass2 = new THREE.Mesh(tubeGeo, coilMaterial);
+        pass2.position.set(depthX * 0.22, ry, 0);
+        group.add(pass1, pass2);
+
+        // U-bend hairpins at both ends
+        const uBendGeo = new THREE.TorusGeometry(depthX * 0.22, 0.02, 8, 16, Math.PI);
+        const uFront = new THREE.Mesh(uBendGeo, mats.copperPipe);
+        uFront.position.set(0, ry, widthZ * 0.5 + 0.04);
+        uFront.rotation.x = Math.PI * 0.5;
+        const uBack = new THREE.Mesh(uBendGeo, mats.copperPipe);
+        uBack.position.set(0, ry, -widthZ * 0.5 - 0.04);
+        uBack.rotation.x = -Math.PI * 0.5;
+        group.add(uFront, uBack);
+      }
+
+      return group;
+    }
