+        // Color by thermodynamic state along the loop
+        if (isCooling) {
+          if (u < 0.22) tmpColor.copy(colHotGas);
+          else if (u < 0.42) tmpColor.copy(colHotGas).lerp(colLiquid, (u - 0.22) / 0.20);
+          else if (u < 0.56) tmpColor.copy(colColdMist);
+          else if (u < 0.80) tmpColor.copy(colColdMist).lerp(colSuction, (u - 0.56) / 0.24);
