+          if (u > 0.55 && u < 0.88) tmpColor.copy(colHotGas);
+          else if (u >= 0.42 && u <= 0.55) tmpColor.copy(colLiquid);
+          else if (u >= 0.14 && u < 0.42) tmpColor.copy(colColdMist);
+          else tmpColor.copy(colSuction);
+        }
