+        refData.colors[i * 3] = tmpColor.r;
+        refData.colors[i * 3 + 1] = tmpColor.g;
+        refData.colors[i * 3 + 2] = tmpColor.b;
+      }
+      refParticles.geometry.attributes.position.needsUpdate = true;
+      refParticles.geometry.attributes.color.needsUpdate = true;
+
+      // 2. Room Air Circulation Particles
+      const roomLanes = isSplit ? splitRoomLanes : monoRoomLanes;
+      const roomData = roomAirParticles.userData;
+      const supplyRoomColor = isCooling ? colRoomChilled : colRoomHeated;
+      for (let i = 0; i < roomData.count; i++) {
