+      document.getElementById('tour-step-tag').textContent = `Guided Explanation · Step ${state.tourStep + 1} of 6`;
+      document.getElementById('tour-title').textContent = stepInfo.title;
+      document.getElementById('tour-body').textContent = stepInfo.body;
+
+      document.querySelectorAll('.step-dot').forEach((dot, idx) => {
+        dot.classList.toggle('active', idx === state.tourStep);
+      });
+
+      Object.entries(pinElements).forEach(([key, el]) => {
+        el.classList.toggle('active-focus', key === stepInfo.focusPin);
+      });
+
+      // Play / Pause button
+      const playLabel = document.getElementById('label-play-pause');
+      const playIcon = document.getElementById('icon-play-pause');
+      playLabel.textContent = state.playing ? 'Pause' : 'Play';
+      playIcon.innerHTML = state.playing
+        ? '<rect x="6" y="4" width="4" height="16" rx="1"></rect><rect x="14" y="4" width="4" height="16" rx="1"></rect>'
+        : '<polygon points="6,4 20,12 6,20"></polygon>';
+
+      // Auto-Guide toggle button
+      const btnAuto = document.getElementById('btn-tour-auto');
+      btnAuto.textContent = `Auto-Guide: ${state.tourAuto ? 'On' : 'Off'}`;
+      btnAuto.classList.toggle('primary', state.tourAuto);
+      btnAuto.setAttribute('aria-pressed', String(state.tourAuto));
+    }
+
+    function setCameraFocus(camPos, camTarget) {
+      if (prefersReducedMotion) return;
+      state.cameraPosLerp = camPos.clone();
+      state.cameraTargetLerp = camTarget.clone();
+      state.cameraTransitionProgress = 0;
+    }
+
+    function goToTourStep(stepIdx, moveCam = false) {
+      state.tourStep = (stepIdx + 6) % 6;
+      state.tourTimer = 0;
+      syncUI();
+      if (moveCam) {
+        const info = getTourStepContent(state.tourStep);
+        setCameraFocus(info.camPos, info.camTarget);
+      }
+    }
+
+    // Attach UI Event Listeners
+    document.getElementById('btn-system-split').addEventListener('click', () => {
+      state.system = 'split';
+      syncUI();
+    });
+
+    document.getElementById('btn-system-monoblock').addEventListener('click', () => {
+      state.system = 'monoblock';
+      syncUI();
+    });
+
+    document.getElementById('btn-mode-cooling').addEventListener('click', () => {
+      state.mode = 'cooling';
+      syncUI();
+    });
+
+    document.getElementById('btn-mode-heating').addEventListener('click', () => {
+      state.mode = 'heating';
+      syncUI();
+    });
+
+    document.getElementById('btn-play-pause').addEventListener('click', () => {
+      state.playing = !state.playing;
+      syncUI();
+    });
+
+    document.getElementById('btn-reset-view').addEventListener('click', () => {
+      state.cameraPosLerp = DEFAULT_CAM_POS.clone();
+      state.cameraTargetLerp = DEFAULT_CAM_TARGET.clone();
+      state.cameraTransitionProgress = 0;
+      if (prefersReducedMotion) {
+        camera.position.copy(DEFAULT_CAM_POS);
+        controls.target.copy(DEFAULT_CAM_TARGET);
+        controls.update();
+      }
+    });
+
+    document.getElementById('btn-tour-prev').addEventListener('click', () => {
+      state.tourAuto = false;
+      goToTourStep(state.tourStep - 1, true);
+    });
+
+    document.getElementById('btn-tour-next').addEventListener('click', () => {
+      state.tourAuto = false;
+      goToTourStep(state.tourStep + 1, true);
+    });
+
+    document.getElementById('btn-tour-auto').addEventListener('click', () => {
+      state.tourAuto = !state.tourAuto;
+      state.tourTimer = 0;
+      syncUI();
+    });
+
+    document.getElementById('btn-tour-replay').addEventListener('click', () => {
+      state.tourAuto = true;
+      state.playing = true;
+      goToTourStep(0, true);
+    });
+
+    document.querySelectorAll('.step-dot').forEach((dot) => {
+      dot.addEventListener('click', () => {
+        const idx = Number(dot.dataset.step);
+        state.tourAuto = false;
+        goToTourStep(idx, true);
+      });
+    });
+
+    document.querySelectorAll('.callout-pin').forEach((pin) => {
+      pin.addEventListener('click', () => {
+        const idx = Number(pin.dataset.step);
+        state.tourAuto = false;
+        goToTourStep(idx, true);
+      });
+    });
+
+    // -------------------------------------------------------------------------
+    // Resize Handling
+    // -------------------------------------------------------------------------
+    window.addEventListener('resize', () => {
+      camera.aspect = window.innerWidth / window.innerHeight;
+      camera.updateProjectionMatrix();
+      renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
+      renderer.setSize(window.innerWidth, window.innerHeight);
+    });
+
+    // -------------------------------------------------------------------------
+    // Main Animation Loop
+    // -------------------------------------------------------------------------
+    const clock = new THREE.Clock();
+    const colorColdCoil = new THREE.Color(0x00d4ff);
+    const colorColdEmissive = new THREE.Color(0x0077aa);
+    const colorHotCoil = new THREE.Color(0xff5e2b);
+    const colorHotEmissive = new THREE.Color(0xcc3300);
+
+    syncUI();
+
+    function animate() {
+      requestAnimationFrame(animate);
+
+      const rawDt = Math.min(clock.getDelta(), 0.08);
+      const dt = state.playing ? rawDt : 0;
+      state.time += dt;
+
+      // Smoothly interpolate modeBlend (0 = cooling, 1 = heating)
+      const targetBlend = state.mode === 'cooling' ? 0 : 1;
+      state.modeBlend = THREE.MathUtils.lerp(state.modeBlend, targetBlend, Math.min(rawDt * 5.5, 1));
+
+      // Update Heat Exchanger Materials & Coil Lights dynamically
+      mats.indoorCoilMat.color.copy(colorColdCoil).lerp(colorHotCoil, state.modeBlend);
+      mats.indoorCoilMat.emissive.copy(colorColdEmissive).lerp(colorHotEmissive, state.modeBlend);
+      mats.outdoorCoilMat.color.copy(colorHotCoil).lerp(colorColdCoil, state.modeBlend);
+      mats.outdoorCoilMat.emissive.copy(colorHotEmissive).lerp(colorColdEmissive, state.modeBlend);
+
+      indoorCoilLight.color.copy(mats.indoorCoilMat.color);
+      outdoorCoilLight.color.copy(mats.outdoorCoilMat.color);
+
+      const isSplit = state.system === 'split';
+      indoorCoilLight.position.set(isSplit ? -0.65 : -0.80, isSplit ? 3.82 : 1.92, 1.05);
+      outdoorCoilLight.position.set(isSplit ? 1.35 : -0.80, isSplit ? 1.05 : 1.12, 0.78);
+
+      // Animate 4-way reversing valve slide indicator position
+      reversingValves.forEach((rv) => {
+        const ind = rv.userData.slideIndicator;
+        if (ind) {
+          ind.position.x = THREE.MathUtils.lerp(-0.035, 0.035, state.modeBlend);
+          ind.rotation.z = state.modeBlend * Math.PI;
+        }
+      });
+
+      // Spin HVAC blower and axial fans when playing
+      if (state.playing) {
+        animatedFans.forEach((f) => {
+          f.mesh.rotation[f.axis] += dt * f.speed;
+        });
+      }
+
+      // Guided explanation auto-advance timer
+      if (state.playing && state.tourAuto) {
+        state.tourTimer += rawDt;
+        if (state.tourTimer >= state.tourStepDuration) {
+          goToTourStep(state.tourStep + 1, false);
+        }
+      }
+
+      // Smooth camera focus transition when triggered by tour navigation or Reset View
+      if (state.cameraTransitionProgress < 1 && state.cameraPosLerp && state.cameraTargetLerp) {
+        state.cameraTransitionProgress = Math.min(1, state.cameraTransitionProgress + rawDt * 2.2);
+        const ease = 1 - Math.pow(1 - state.cameraTransitionProgress, 3);
+        camera.position.lerp(state.cameraPosLerp, ease * 0.16);
+        controls.target.lerp(state.cameraTargetLerp, ease * 0.16);
+      }
+
+      controls.update();
+      updateAllParticles(dt);
+      updateOverlayLabels();
+      renderer.render(scene, camera);
+    }
+
+    animate();
+  </script>
+</body>
+</html>

