python3 -m http.server 8765 --bind 127.0.0.1 >/dev/null 2>&1 &
SERVER_PID=$!
trap "kill $SERVER_PID 2>/dev/null" EXIT
sleep 0.5
node -e '
(async () => {
  let playwright;
  try {
    playwright = require("playwright");
  } catch {
    const res = await fetch("http://127.0.0.1:8765/index.html");
    const html = await res.text();
    console.log("HTTP_STATUS:", res.status, "LENGTH:", html.length);
    process.exit(0);
  }
  const browser = await playwright.chromium.launch();
  const page = await browser.newPage();
  const errors = [];
  page.on("pageerror", e => errors.push(e.message));
  page.on("console", m => { if (m.type() === "error") errors.push(m.text()); });
  await page.goto("http://127.0.0.1:8765/index.html", { waitUntil: "networkidle" });
  const title = await page.title();
  const h1 = await page.textContent("#primary-title");
  await page.click("#btn-system-monoblock");
  const stateMono = await page.textContent("#system-state-text");
  await page.click("#btn-mode-heating");
  const stateHeat = await page.textContent("#system-state-text");
  await page.click("#btn-system-split");
  await page.click("#btn-mode-cooling");
  await page.click("#btn-play-pause");
  const playLabel = await page.textContent("#label-play-pause");
  await page.click("#btn-tour-next");
  const stepTag = await page.textContent("#tour-step-tag");
  await page.click("#btn-reset-view");
  await browser.close();
  console.log(JSON.stringify({ title, h1: h1.trim(), stateMono, stateHeat, playLabel, stepTag, errors }));
})();
'

