const fs = require("fs");
const html = fs.readFileSync("index.html", "utf8");
const match = html.match(/<script type="module">([\s\S]*?)<\/script>/);
if (!match) throw new Error("No module script found");
const vm = require("vm");
new vm.SourceTextModule ? console.log("SourceTextModule supported") : null;
// Check balanced tags & required IDs
const requiredIds = [
  "primary-title", "btn-system-split", "btn-system-monoblock",
  "btn-mode-cooling", "btn-mode-heating", "btn-play-pause",
  "btn-reset-view", "btn-tour-prev", "btn-tour-next",
  "btn-tour-auto", "btn-tour-replay", "canvas-container"
];
for (const id of requiredIds) {
  if (!html.includes(`id="${id}"`)) throw new Error("Missing ID: " + id);
}
const titleMatch = html.match(/<title>(.*?)<\/title>/);
const h1Match = html.match(/<h1 id="primary-title">(.*?)<\/h1>/);
console.log("TITLE:", titleMatch[1], "H1:", h1Match[1]);
' && node --input-type=module --check < <(awk '/<script type="module">/{flag=1;next}/<\/script>/{flag=0}flag' index.html) && echo "SYNTAX_OK"

